 class Task implements Callable<String> {
    int k,c,s;
    public Task(int k,int c,int s) {
        this.k = k;
        this.c = c;
        this.s = s;
    }

    @Override
    public String call() throws Exception {

        long second = 0;
        for(int i=0;i<c;i++) {
            second = second * k + 1;
        }
        StringBuilder sb = new StringBuilder();
        for(int i=0;i<k;i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(second * i + 1);
        }
        return sb.toString();
    }

 }

