package b;














 public class Main {

    public static void main(String[] args) throws Exception {
        Solver<Object> solver = Solver.getInstance("B-small-attempt0.in");
        Scanner sc = solver.getScanner();
        int casenum = sc.nextInt();
        for(int caseid=0;caseid<casenum;caseid++) {
            char[] s = sc.next().toCharArray();
            int n = s.length;
            int[] a = new int[n];
            for(int i=0;i<n;i++) {
                a[i] = s[i] - '0';
            }
            solver.addTask(new Task(n, a));
        }
        solver.finish();
    }

 }
 class Task implements Callable<Object> {
    int n;
    int[] a;

    public Task(int n, int[] a) {
        super();
        this.n = n;
        this.a = a;
    }

    @Override
    public Object call() throws Exception {
        int[] b = new int[n];
        LOOP: for(int i=0;i<n;i++) {
            for(int j=9;j>=0;j--) {
                for(int k=i;k<n;k++) {
                    b[k] = j;
                }
                if (toi(a) >= toi(b)) {
                    continue LOOP;
                }
            }
        }
        return toi(b);
    }

    public static long toi(int[] a) {
        long x = 0;
        for(int i=0;i<a.length;i++) {
            x = x * 10 + a[i];
        }
        return x;
    }
 }

