                        {
                            grid[row][col]= 0;
                            base++;
                        }

                }
                unhappy = new ArrayList<Integer>();

                for (int row = 0; row < grid.length; row++)
                {
                    for (int col = 0; col < grid[0].length; col++)
                        if (grid[row][col]== -1)
                        {
                            int unhappyNext = 4;
                            if (row == 0)
                                unhappyNext--;
                                if (row == grid.length-1)
                                    unhappyNext--;
