                Collections.sort(unhappy);
                unhappiness = 0;



                for (int i = 0; i < unhappy.size() && base < N; i++)
                {
                    unhappiness += unhappy.get(i);
                    base++;
                }

                unhappiness = Math.min(unhappiness, firstUnhappiness);
