        }


        System.out.print(ans.toString());
        out.write(ans.toString());
        out.flush();
        out.close();
    }



    private int solve()
    {

        int max = Integer.MIN_VALUE;
        for (int i : arr)
            max = Math.max(max, i);
        int ans = max;
        for (int maxLeft = 1; maxLeft <= max; maxLeft++)
        {
            int sum = maxLeft;
            for (int x : arr)
            {
                int parts = x / maxLeft;
                if (parts * maxLeft < x)
                    parts ++;
                sum += parts - 1;
            }
            ans = Math.min(ans, sum);
        }
        return ans;
    }

 }
