        for (;;) {
            boolean change = false;
            for (int i = 0; i + 1 < s.length; i++) {
                if (s[i] > s[i+1]) {
                    s[i]--;
                    for (int j = i + 1; j < s.length; j++) s[j] = '9';
                    change = true;
                    break;
                }
            }
            if (!change) break;
        }
        String ans = new String(s);
        while (ans.charAt(0) == '0') ans = ans.substring(1);
        out.println(ans);
    }

