public class B_1C_GCJ2015 {

     public static long MOD = 1000000007;
     static int[][] other;
     static double[][] dp;

     public static void main(String[] args) throws FileNotFoundException {
         PrintWriter out = new PrintWriter(new FileOutputStream(new File(
                 "output.txt")));

         Scanner in = new Scanner();
         int t = in.nextInt();
         for (int z = 0; z < t; z++) {
             int k = in.nextInt();
             int l = in.nextInt();
             int s = in.nextInt();
             String key = in.next();
             String target = in.next();
             double result = 0;
             boolean[] check = new boolean[26];
             for (int i = 0; i < k; i++) {
                 check[key.charAt(i) - 'A'] = true;
             }
             boolean ok = true;
             for (int i = 0; i < l; i++) {
                 if (!check[target.charAt(i) - 'A']) {
                     ok = false;
                     break;
                 }
             }
             if (s >= l && ok) {
                 int[] kmp = KMP(target);
                 other = new int[s][s];
                 for (int[] a : other) {
                     Arrays.fill(a, -1);
                 }
                 dp = new double[s][l];
                 for (double[] a : dp) {
                     Arrays.fill(a, -1);
                 }
                 int max = max(0, l - 1, s, target);
                 double v = cal(0, 0, s, kmp, key, target);

                 result = max - v;
             }
             out.println("Case #" + (z + 1) + ": " + result);

         }
         out.close();
     }

     public static double cal(int index, int cur, int s, int[] kmp, String key, String t) {
         if (index == s) {
             return 0;
         }
         if (dp[index][cur] != -1) {
             return dp[index][cur];
         }
         double prob = 1.0 / key.length();
         double result = 0;
         for (int i = 0; i < key.length(); i++) {
             int j = cur;
             while (j >= 0 && key.charAt(i) != t.charAt(j)) {
                 j = kmp[j];
             }
             j++;
             int add = 0;
             if (j == t.length()) {
                 add = 1;
                 j = kmp[j];
             }
             result += prob * (add + cal(index + 1, j, s, kmp, key, t));

         }
         return dp[index][cur] = result;

     }

     public static int max(int index, int end, int s, String t) {
         if (index == s) {
             return 0;
         }
         if (other[index][end] != -1) {
             return other[index][end];
         }
         int result = 0;
         if (index == end + 1) {
             if (t.length() + index <= s) {
                 result = 1 + max(index + 1, t.length() + index - 1, s, t);
             }
         } else {
             int pos = t.length() - (end - index + 1);
             if (t.startsWith(t.substring(pos)) && t.length() + index <= s) {
                 result = 1 + max(index + 1, t.length() + index - 1, s, t);
             }
             result = Math.max(result, max(index + 1, end, s, t));
         }
         return other[index][end] = result;

     }

     public static int[] KMP(String val) {
         int i = 0;
         int j = -1;
         int[] result = new int[val.length() + 1];
         result[0] = -1;
         while (i < val.length()) {
             while (j >= 0 && val.charAt(j) != val.charAt(i)) {
                 j = result[j];
             }
             j++;
             i++;
             result[i] = j;
         }
         return result;

     }

     public static boolean nextPer(int[] data) {
         int i = data.length - 1;
         while (i > 0 && data[i] < data[i - 1]) {
             i--;
         }
         if (i == 0) {
             return false;
         }
         int j = data.length - 1;
         while (data[j] < data[i - 1]) {
             j--;
         }
         int temp = data[i - 1];
         data[i - 1] = data[j];
         data[j] = temp;
         Arrays.sort(data, i, data.length);
         return true;
     }

     public static int digit(long n) {
         int result = 0;
         while (n > 0) {
             n /= 10;
             result++;
         }
         return result;
     }

     public static double dist(long a, long b, long x, long y) {
         double val = (b - a) * (b - a) + (x - y) * (x - y);
         val = Math.sqrt(val);
         double other = x * x + a * a;
         other = Math.sqrt(other);
         return val + other;



     }

     public static class Point implements Comparable<Point> {

         int x, y;

         public Point(int start, int end) {
             this.x = start;
             this.y = end;
         }

