                allSize += size[v];
            }
            for (int i = st; i < en; i++) {
                prob[i] = allProb / (c[allSize][size[q[i]]] * dp[q[i]]);
                int sz = allSize - size[q[i]];

                for (int v : g[q[i]]) {
                    prob[i] = c[sz + size[v]][sz] * prob[i] * dp[v];
                    sz += size[v];
                }

                sum += prob[i];
            }
            double dice = rng.nextDouble();
            double curProb = 0;
            for (int i = st; i < en; i++) {
                prob[i] /= sum;
                curProb += prob[i];
                if (curProb >= dice || i + 1 == en) {
                    int tmp = q[i];
                    q[i] = q[st];
                    q[st] = tmp;
                    break;
                }
            }
            int x = q[st++];
            sb.append(let[x]);
            for (int v : g[x]) {
                q[en++] = v;
            }
        }
        return sb.toString();

