            }
            f[0]--;
            long sum = 0;
            for (int i = 0; i < p; i++) {
                sum += f[i];
            }
            int cnt = 1;
            while (1L << cnt < sum) {
                cnt++;
            }
            int[] all = new int[cnt];
            int cur = 0;
            int[] summ = new int[1 << cnt];
            {
                int i = 0;
                while (cur < cnt) {
                    if (f[i] > 0) {
                        all[cur++] = e[i];
                        for (int st = 0; st < 1 << (cur - 1); st++) {
                            summ[st | (1 << (cur - 1))] = summ[st]
                                    + all[cur - 1];
                            int le = 0, ri = p;
                            int need = summ[st] + all[cur - 1];
                            while (ri - le > 1) {
                                int mid = (le + ri) >>> 1;
                                if (e[mid] <= need) {
                                    le = mid;
                                } else {
                                    ri = mid;
                                }
                            }
