        for(int i=0;i<D.length;i++)for(int j=i+1;j<D.length;j++){
            DD[i][j]=DD[i][j-1]+D[j-1][j];
        }
        M = new double[n][n];
        for(double[]m:M)Arrays.fill(m, -1);
        return doit(0,0);
    }
