     public void solve(int testNumber, InputReader in, PrintWriter out) {
         out.print("Case #"+testNumber+": ");
         int N = in.nextInt();
         int A = 0;
         int B = 0;
         int[] m = new int[N];
         int maxdiff = 0;
         for (int i = 0; i < N; i++) {
             m[i] = in.nextInt();
             if (i > 0) {
                 int diff = Math.max(0, m[i - 1] - m[i]);
