                 for (char c : digits) {
                     seen[c - '0'] = true;
                 }
                 if (seenAll(seen)) {
                     print(i, kn);
                     break;
                 } else {
                     kn += n;
                 }
             }
         }
         sc.close();
         System.err.println(System.currentTimeMillis() - time);
     }

     private static boolean seenAll(boolean[] arr) {
         for (boolean b : arr) {
             if (!b) {
                 return false;
             }
         }
         return true;
     }

     private static void print(int caseNum, long answer) {
         System.out.println("Case #" + caseNum + ": " + (answer == -1 ? "INSOMNIA" : answer));
     }

