         int score = 0;
         int code = 0;
         int jam = 0;
         Stack<Character> stk = new Stack<>();
         for (int i = 0 ; i < n ; i++) {
             if (stk.size() == 0) {
                 stk.push(mood[i]);
             } else {
                 if (stk.peek() == mood[i]) {
                     stk.pop();
                     score += 10;
                 } else {
                     int pool = stk.size();
                     int left = n - i;
                     if (pool + 1 <= left - 1) {
                         stk.push(mood[i]);
                     } else {
                         stk.pop();
                         score += 5;
                     }
                 }
             }
         }
         return score;
     }
