            cs = new char[h][];
            for(int i = 0; i < h; i++) {
                cs[i] = io.next();
            }
        }

        @Override
        public void run() {
            int ans = 0;
            for(int y = 0; y < h; y++) {
                for(int x = 0; x < w; x++) {
                    if(cs[y][x] == '.') continue;
                    int cost = Integer.MAX_VALUE;
                    for(int i = 0; i < 4; i++) {
                        if(find(x, y, "<^>v".charAt(i))) {
                            cost = Math.min(cost, "<^>v".charAt(i) == cs[y][x] ? 0 : 1);
                        }
                    }
                    if(cost == Integer.MAX_VALUE) {
                        out.println("IMPOSSIBLE");
                        return;
                    }
                    ans += cost;
                }
            }
            out.println(ans);
        }

        boolean find(int x, int y, char c) {
            if(c == '<') return find(x, y, -1, 0);
            if(c == '>') return find(x, y, 1, 0);
            if(c == '^') return find(x, y, 0, -1);
            if(c == 'v') return find(x, y, 0, 1);
            throw new RuntimeException();
        }
        boolean find(int x, int y, int dx, int dy) {
            x += dx;
            y += dy;
            for(; x >= 0 && x < w && y >= 0 && y < h; x += dx, y += dy) {
                if(cs[y][x] != '.') {
                    return true;
                }
            }
            return false;
        }




