            for (int i = 0; i < a.length; i++) if (a[i] != b[i]) return a[i] - b[i];
            return 0;
        });

        TreeSet<int[]> vis2 = new TreeSet<>((a,b)->{
            for (int i = 0; i < a.length; i++) if (a[i] != b[i]) return a[i] - b[i];
            return 0;
        });

        int dfs(int[] cur) {
            if (!vis.add(cur.clone())) {
                return 0;
            }

            int[] next = new int[cs.length];
            Arrays.fill(next, 0);
            return 1 + gen(cur, next);
        }

        int[] key;
        int gen(int[] count, int[] next) {
            System.arraycopy(count, 0, key, 0, count.length);
            System.arraycopy(next, 0, key, count.length, next.length);
            if (vis2.contains(key)) {
                return 0;
            }
            vis2.add(key.clone());

            for (int i = 0; i < count.length; i++) if (count[i] > 0) {
                int res = 0;
                for (int j = 0; j < cs.length; j++) if (next[j] == 0) {
                    count[i]--;
                    next[j] = i + 1;
                    res += gen(count, next);
                    count[i]++;
                    next[j] = 0;
                }
                return res;
            }
            return dfs(next);
        }



