            int ma = 0;
            int f = 0;
            for (int i = 0; i < n; i++) {
                ar[i] = in.nextInt();
                if (i > 0) {
                    ma = Math.max(ma, ar[i - 1] - ar[i]);
                    if (ar[i] < ar[i-1]){
                        f += ar[i - 1] - ar[i];
                    }
                }
            }

            int s = 0;
            for (int i = 1; i < n; i++) {
                if (ar[i - 1] >= ma) {
                    s += ma;
                } else {
                    s += ar[i - 1];
                }
            }
            System.out.println("Case #" + t + ": " + f + " " + s);
        }
    }
 }
