        {
            int hitway = R-1+ ((C>W)?W+1:W);
            if(C<2*W)
            {
                return hitway;
            }
            int missway = R+Math.min(recsolv(W,W,R)+recsolv(C-W-1,W,R),recsolv(C-W,W,R));
            return Math.max(hitway, missway);
        }
