        || (edge.p2.y < p.y && edge.p1.y >= p.y)) {
        if (edge.p1.x + (p.y-edge.p1.y)/(edge.p2.y-edge.p1.y)*(edge.p2.x-edge.p1.x) < p.x) {
            ret = !ret;
        }
        }
    }
    return ret;
     }

     public boolean isInside(Point p, FixDoubleComparator comparator) {
