    String fnc(String s, int k) {
        String ans = "";

        boolean[] b = new boolean[s.length()];
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '+') {
                b[i] = true;
            }
        }

        int cnt = 0;
        for (int i = 0; i <= s.length() - k; i++) {
            if (!b[i]) {
                cnt++;
                for (int j = 0; j < k; j++) {
                    b[i+j] ^= true;
                }
            }
        }

        ans = "" + cnt;
        for (int i = s.length() - k; i < s.length(); i++) {
            if (!b[i]) {
                ans = "IMPOSSIBLE";
                break;
            }
        }

        return ans;
    }

    public static void main(String[] args) {
        new A().run();
    }
