            nr = r+1;
            nc = c;
            if(!used[nr][nc] && a[nr][nc] == target){
                used[nr][nc] = true;
                find(used, nr, nc, target);
            }
        }
        if(r > 0){
            nr = r-1;
            nc = c;
            if(!used[nr][nc] && a[nr][nc] == target){
                used[nr][nc] = true;
                find(used, nr, nc, target);
            }
        }
        if(c < C-1){
            nr = r;
            nc = c+1;
            if(!used[nr][nc] && a[nr][nc] == target){
                used[nr][nc] = true;
                find(used, nr, nc, target);
            }
        }
        if(c > 0){
            nr = r;
            nc = c-1;
            if(!used[nr][nc] && a[nr][nc] == target){
                used[nr][nc] = true;
                find(used, nr, nc, target);
            }
        }
    }


