     static class TaskC {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             out.print("Case #" + testNumber + ": ");
             int j = in.readInt();
             int p = in.readInt();
             int s = in.readInt();
             int limit = in.readInt();

             Counter<String> counter = new Counter<String>();

             List<String> answer = new ArrayList<String>();

             for (int i = 1; i <= j; i++) {
                 for (int k = 1; k <= p; k++) {
                     for (int l = 1; l <= s; l++) {
                         StringBuilder all = new StringBuilder();
                         StringBuilder jp = new StringBuilder();
                         StringBuilder js = new StringBuilder();
                         StringBuilder ps = new StringBuilder();

                         all.append(i).append(k).append(l);
                         jp.append(i).append(k).append(0);
                         js.append(i).append(0).append(l);
                         ps.append(0).append(k).append(l);

                         if (counter.get(all.toString()) > 0) {
                             continue;
                         }

                         if (counter.get(jp.toString()) >= limit) {
                             continue;
                         }

                         if (counter.get(js.toString()) >= limit) {
                             continue;
                         }

                         if (counter.get(ps.toString()) >= limit) {
                             continue;
                         }

                         counter.add(all.toString());
                         counter.add(jp.toString());
                         counter.add(js.toString());
                         counter.add(ps.toString());
                         answer.add(i + " " + k + " " + l);
                     }
                 }
             }

             out.printLine(answer.size());

             for (String x : answer) {
                 out.printLine(x);
             }
         }

     }

