       this.pp = pp;
       this.min = min;
       this.max = max;

       perm = new int[p];
       used = new boolean[p];
     }

     void gen(int k) {
       if (k == p) {
         check();
         return;
       }
       for (int i = 0; i < p; i++) {
         if (!used[i]) {
           perm[k] = i;
           used[i] = true;
           gen(k + 1);
           used[i] = false;
         }
       }
     }

     int val = 0;

     private void check() {
       System.out.println(Arrays.toString(perm));
       int res = 0;
       for (int i = 0; i < p; i++) {
         if (Math.max(min[0][i], min[1][perm[i]]) <= Math.min(max[0][i], max[1][perm[i]])) {
           res++;
         }
       }
       val = Math.max(val, res);
     }

   }
