            for (int j = i + 1; j < N; j++) {
                side[0] = side[1] = 0;
                long A = y[i] - y[j], B = x[j] - x[i], C = -(x[i] * A + y[i]
                        * B);
                for (int k = 0; k < N; k++) {
                    long T = A * x[k] + B * y[k] + C;
                    if (T > 0)
                        side[0]++;
                    if (T < 0)
                        side[1]++;
                }
                log[i] = Math.min(log[i], Math.min(side[0], side[1]));
                log[j] = Math.min(log[j], Math.min(side[0], side[1]));
            }
        }
