     private int getDigitMask(long x) {
         int mask = 0;
         while (x > 0) {
             mask |= (1 << (x % 10));
             x /= 10;
         }
         return mask;
     }

     private void solve(Kattio io) {
         long n = io.getLong();
         long last = solve(n);
         if (last < 0) {
             io.println("INSOMNIA");
         } else {
             io.println(last);
         }
     }

     private long solve(long n) {
         if (n == 0) return -1;
         long cur = 0;
         int seen = 0;
         while (seen != 1023) {
             cur += n;
             seen |= getDigitMask(cur);
         }
         return cur;
     }
 }
