     private double evenProb(double[] p) {
         int k = p.length/2;
         double[] yes = new double[k+1];
         yes[0] = 1.0;
         for (int i = 0; i < p.length; i++) {
             double[] oldyes = yes;
             yes = new double[k+1];
             for (int j = 0; j <= k; j++) {
                 yes[j] = oldyes[j] * (1-p[i]) + (j > 0 ? oldyes[j-1]*p[i] : 0);
             }
         }
         return yes[k];
     }

     private void solve(Kattio io) {
         int N = io.getInt(), K = io.getInt();
         double max = 0.0;
         double p[] = new double[N];
         double best[] = null;
         for (int i = 0; i < N; i++) {
             p[i] = io.getDouble();
         }
         Arrays.sort(p);

         for (int mask = 0; mask < (1 << N); mask++) {
             double pselected[] = new double[K];
             int cnt = 0;
             for (int i = 0; i < N; i++) {
                 if (((1<<i)&mask)>0) {
                     if (cnt < K) {
                         pselected[cnt] = p[i];
                     }
                     cnt++;
                 }
             }
             if (cnt == K) {
                 double v = evenProb(pselected);
                 if (v > max) {
                     max = v;
                     best = pselected.clone();
                 }
             }
         }
         io.println(String.format("%.10f", max));



     }
 }
