public class Main {
     public static void main(String[] args) {
         Locale.setDefault(Locale.US);
         InputStream inputStream;
         try {
             final String regex = "B-(small|large).*[.]in";
             File directory = new File(".");
             File[] candidates = directory.listFiles(new FilenameFilter() {
                 public boolean accept(File dir, String name) {
                     return name.matches(regex);
                 }
             });
             File toRun = null;
             for (File candidate : candidates) {
                 if (toRun == null || candidate.lastModified() > toRun.lastModified()) {
                     toRun = candidate;
                 }
             }
             inputStream = new FileInputStream(toRun);
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         OutputStream outputStream;
         try {
             outputStream = new FileOutputStream("b.out");
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         InputReader in = new InputReader(inputStream);
         OutputWriter out = new OutputWriter(outputStream);
         TaskB solver = new TaskB();
         solver.solve(1, in, out);
         out.close();
     }

     static class TaskB {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
                 int f;
                 int p;
                 int[] a;
                 int[] b;


                 public void read(InputReader in) {
                     f = in.readInt();
                     p = in.readInt();
                     a = new int[p];
                     b = new int[p];
                     IOUtils.readIntArrays(in, a, b);
                 }

                 int[] answer;

                 Graph graph;
                 boolean[] was;


                 public void solve() {
                     MiscUtils.decreaseByOne(a, b);
                     answer = new int[p];
                     graph = BidirectionalGraph.createGraph(f, a, b);
                     was = new boolean[f];
                     for (int i = 0; i < p; i++) {
                         if (answer[i] != 0) {
                             continue;
                         }
                         Arrays.fill(was, false);
                         IntList path = getPath(b[i], a[i], i);
                         if (path == null) {
                             answer = null;
                             return;
                         }
                         IntSet forbidden = new IntHashSet();
                         int current = a[i];
                         for (int j : path) {
                             if (current == a[j]) {
                                 forbidden.add(-answer[j]);
                                 current = b[j];
                             } else {
                                 forbidden.add(answer[j]);
                                 current = a[j];
                             }
                         }
                         int change = 0;
                         for (int j = 1; ; j++) {
                             if (!forbidden.contains(j)) {
                                 change = j;
                                 break;
                             }
                             if (!forbidden.contains(-j)) {
                                 change = -j;
                                 break;
                             }
                         }
                         answer[i] = -change;
                         current = a[i];
                         for (int j : path) {
                             if (current == a[j]) {
                                 answer[j] += change;
                                 current = b[j];
                             } else {
                                 answer[j] -= change;
                                 current = a[j];
                             }
                         }
                     }
                     for (int i = 0; i < p; i++) {
                         if (Math.abs(answer[i]) > f * f) {
                             throw new RuntimeException();
                         }
                     }
                 }

                 private IntList getPath(int from, int to, int forbiddenEdge) {
                     if (was[from]) {
                         return null;
                     }
                     was[from] = true;
                     if (from == to) {
                         return new IntArrayList();
                     }
                     for (int i = graph.firstOutbound(from); i != -1; i = graph.nextOutbound(i)) {
                         if ((i >> 1) == forbiddenEdge) {
                             continue;
                         }
                         IntList call = getPath(graph.destination(i), to, forbiddenEdge);
                         if (call != null) {
                             call.add(i >> 1);
                             return call;
                         }
                     }
                     return null;
                 }


                 public void write(OutputWriter out, int testNumber) {
                     out.print("Case #" + testNumber + ": ");
                     if (answer == null) {
                         out.printLine("IMPOSSIBLE");
                     } else {
                         out.printLine(answer);
                     }
                 }
             }, 4);
         }

     }

