 class TaskC {
     public void solve(int testNumber, InputReader in, OutputWriter out) {
         Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
             int count;
             String[][] sentences;
             int answer = 0;

             public void read(InputReader in) {
                 count = in.readInt();
                 sentences = new String[count][];
                 for (int i = 0; i < count; i++) {
                     sentences[i] = in.readLine().split(" ");
                 }
             }

             public void solve() {
                 int[][] id = new int[count][];
                 Indexer<String> indexer = new Indexer<>();
                 for (int i = 0; i < count; i++) {
                     id[i] = new int[sentences[i].length];
                     for (int j = 0; j < id[i].length; j++) {
                         id[i][j] = indexer.get(sentences[i][j]);
                     }
                 }
                 answer = Integer.MAX_VALUE;
                 int[] type = new int[indexer.size()];
                 for (int i = 0; i < (1 << (count - 2)); i++) {
                     int mask = 2 + 4 * i;
                     Arrays.fill(type, 0);
                     for (int j = 0; j < count; j++) {
                         for (int k : id[j]) {
                             type[k] |= 1 << ((mask >> j) & 1);
                         }
                     }
                     answer = Math.min(answer, ArrayUtils.count(type, 3));
                 }
             }

             public void write(OutputWriter out, int testNumber) {
                 out.printLine("Case #" + testNumber + ":", answer);
             }
         }, 4);
     }
 }

 class InputReader {

    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    private String readLine0() {
        StringBuilder buf = new StringBuilder();
        int c = read();
        while (c != '\n' && c != -1) {
            if (c != '\r')
                buf.appendCodePoint(c);
            c = read();
        }
        return buf.toString();
    }

    public String readLine() {
        String s = readLine0();
        while (s.trim().length() == 0)
            s = readLine0();
        return s;
    }

    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }
 }

