                {
                    if(!can(j,sa,fa))ok=false;
                }
                if(!ok)break;
            }
            if(ok)
                return true;

        }
        return false;
    }


    boolean can(int x, int [] s, int []f)
    {
        for(int i=0; i<s.length; i++)
            if(x>=s[i]&&x<f[i])return false;
        return true;
    }

