                 for (int y = height - 2; y >= 0; y--) {
                     for (int x = 0; x < width; x++) {
                         if (cake[y][x] == '?') cake[y][x] = cake[y + 1][x];
                     }
                 }
                 for (int y = 1; y < height; y++) {
                     for (int x = 0; x < width; x++) {
                         if (cake[y][x] == '?') cake[y][x] = cake[y - 1][x];
                     }
                 }
                 System.out.printf("Case #%d:%n", t);
                 for (int y = 0; y < height; y++) System.out.println(new String(cake[y]));
