public class B {
    String s, t;

    String solve() {
        int n = s.length();
        int[] a = new int[n];
        int[] b = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = s.charAt(i) == '?' ? -1 : s.charAt(i) - '0';
            b[i] = t.charAt(i) == '?' ? -1 : t.charAt(i) - '0';
        }
        {
            boolean canBeEqual = true;
            String ans = ""; 
            for (int i = 0; i < n; i++) {
                if (a[i] == -1 && b[i] == -1) {
                    ans += "0";
                    continue;
                }
                if (a[i] != -1 && b[i] != -1) {
                    if (a[i] != b[i]) {
                        canBeEqual = false;
                    }
                    ans += a[i];
                    continue;
                }
                ans += a[i] + b[i] + 1;
            }
            if (canBeEqual) {
                return ans + " " + ans;
            }
        }
        long bestA = -1, bestB = -1;
        for (int larger = 0; larger < 2; larger++) {
            for (int d = 0; d < n; d++) {
                boolean possible = true;
                int[] aa = new int[n];
                int[] bb = new int[n];
                for (int i = 0; i < n; i++) {
                    if (i < d) {
                        if (a[i] == -1 && b[i] == -1) {
                            aa[i] = bb[i] = 0;
                            continue;
                        }
                        if (a[i] != -1 && b[i] != -1) {
                            if (a[i] != b[i]) {
                                possible = false;
                            }
                            aa[i] = bb[i] = a[i];
                            continue;
                        }
                        aa[i] = bb[i] = a[i] + b[i] + 1;
                        continue;
                    }
                    if (i > d) {
                        int[] c = a;
                        int[] cc = aa;
                        int[] e = b;
                        int[] ee = bb;
                        if (larger == 1) {
                            c = b;
                            cc = bb;
                            e = a;
                            ee = aa;
                        }
                        if (c[i] == -1) {
                            cc[i] = 0;
                        } else {
                            cc[i] = c[i];
                        }
                        if (e[i] == -1) {
                            ee[i] = 9;
                        } else {
                            ee[i] = e[i];
                        }
                        continue;
                    }
                    boolean found = false;
                    loop:
                    for (int diff = 1; diff <= 9; diff++) {
                        for (aa[i] = 0; aa[i] <= 9; aa[i]++) {
                            if (larger == 0) {
                                bb[i] = aa[i] - diff;
                            } else {
                                bb[i] = aa[i] + diff;
                            }
                            if (bb[i] < 0 || bb[i] > 9) {
                                continue;
                            }
                            if (a[i] != -1 && a[i] != aa[i]) {
                                continue;
                            }
                            if (b[i] != -1 && b[i] != bb[i]) {
                                continue;
                            }
                            found = true;
                            break loop;
                        }
                    }
                    if (!found) {
                        possible = false;
                    }
                }
                if (!possible) {
                    continue;
                }
                long curA = make(aa);
                long curB = make(bb);
                if (bestA == -1 || Math.abs(curA - curB) < Math.abs(bestA - bestB) ||
                        Math.abs(curA - curB) == Math.abs(bestA - bestB) && curA < bestA ||
                        Math.abs(curA - curB) == Math.abs(bestA - bestB) && curA == bestA && curB < bestB) {
                    bestA = curA;
                    bestB = curB;
                }
            }
        }
        return pad(bestA, n) + " " + pad(bestB, n);
    }

    static long make(int[] a) {
        long res = 0;
        for (int d : a) {
            res = 10 * res + d;
        }
        return res;
    }

    static String pad(long v, int n) {
        String s = "" + v;
        while (s.length() < n) {
            s = "0" + s;
        }
        return s;
    }

    public B(Scanner in) {
        s = in.next();
        t = in.next();
    }

    public static void main(String[] args) throws Exception {
        int nThreads = 4;

